mapper.update:
UPDATE reconcile_run
SET status = 'FAILED', error = #{error}, finished_at = now()
WHERE run_id = #{runId}

UPDATE reconcile_finding
SET status = 'SUPERSEDED',
    settled_at = now(),
    settle_reason = '本轮扫描未再发现该差异（在扫描范围内自动退场）'
WHERE tenant_id = #{tenantId}
  AND hotel_id = #{hotelId}
  AND status = 'OPEN'
  AND last_run_id <> #{runId}
  AND (stay_date IS NULL
       OR (stay_date >= #{from}::date AND stay_date < #{to}::date))

UPDATE reconcile_finding
SET status = 'REPAIRED',
    repaired_at = now(),
    settled_at = now(),
    settle_reason = '按权威记录重建派生数据'
WHERE tenant_id = #{tenantId}
  AND hotel_id = #{hotelId}
  AND finding_id = #{findingId}
  AND status = 'OPEN'
  AND severity = 'DERIVED'

UPDATE reconcile_finding
SET status = 'IGNORED',
    settled_at = now(),
    settled_by = #{operator},
    settle_reason = #{reason}
WHERE tenant_id = #{tenantId}
  AND hotel_id = #{hotelId}
  AND finding_id = #{findingId}
  AND status = 'OPEN'

mapper.select:
SELECT 
FROM reconcile_finding
WHERE tenant_id = #{tenantId} AND hotel_id = #{hotelId} AND finding_id = #{findingId}

SELECT 
FROM reconcile_finding
WHERE tenant_id = #{tenantId}
  AND hotel_id = #{hotelId}
  AND status = 'OPEN'

  AND severity = #{severity}

ORDER BY CASE severity WHEN 'FACT' THEN 0 WHEN 'BACKLOG' THEN 1 ELSE 2 END,
         last_seen_at DESC
LIMIT #{limit}

SELECT 
FROM reconcile_finding
WHERE tenant_id = #{tenantId}
  AND hotel_id = #{hotelId}
  AND status <> 'OPEN'
ORDER BY settled_at DESC NULLS LAST
LIMIT #{limit}

SELECT count(*)
FROM reconcile_finding
WHERE tenant_id = #{tenantId}
  AND hotel_id = #{hotelId}
  AND status = 'OPEN'
  AND severity = #{severity}

SELECT scanned_through
FROM reconcile_watermark
WHERE tenant_id = #{tenantId} AND hotel_id = #{hotelId}
